"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["77575"],{37757(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.nome_caractere_invalido","status":422,"titulo":"Nome do tipo de conceito cont\xe9m o caractere nulo ou caractere que n\xe3o \xe9 texto"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.nome_caractere_invalido","requisitos":[],"oQueAconteceu":["O `nome` enviado na cria\xe7\xe3o (`POST /api/configuracao/admin/tipos-conceito`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) tem o caractere nulo (`U+0000`), um caractere de controle (como a quebra de linha ou a tabula\xe7\xe3o) ou de formata\xe7\xe3o, ou texto que n\xe3o \xe9 Unicode v\xe1lido.","A recusa vem na lista `errors` da resposta, com `field` igual a `nome`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, com o corpo desserializ\xe1vel e o `id` do corpo igual ao da rota, a confer\xeancia do corpo vem antes da busca do tipo: com um `{id}` que n\xe3o existe, a resposta \xe9 esta, e n\xe3o a de [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado). O corpo que n\xe3o desserializa e o `id` do corpo diferente do da rota s\xe3o recusados antes, com 400 e sem o c\xf3digo desta p\xe1gina."],"comoResolver":["Remova o caractere inv\xe1lido do nome e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito","Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);